export function ageInYears(birthDate:string,now=new Date()):number {
  const birth=new Date(`${birthDate.slice(0,10)}T00:00:00Z`); if(!Number.isFinite(birth.getTime())||birth>now)return -1;
  let age=now.getUTCFullYear()-birth.getUTCFullYear(); if(now.getUTCMonth()<birth.getUTCMonth()||(now.getUTCMonth()===birth.getUTCMonth()&&now.getUTCDate()<birth.getUTCDate()))age--;return age;
}
